<template>
 <el-dialog :title="titles[kind]" :visible.sync="visible" width="min(1050px,96vw)" append-to-body :close-on-click-modal="false">
  <template v-if="detail">
   <el-alert :title="hint" type="info" :closable="false"/>
   <template v-if="kind==='REMAINING'"><el-radio-group v-model="choice" class="choices"><el-radio v-if="detail.state!=='CANCELED'" v-hasPermi="['warehouse:purchaseReturn:cancel']" label="STOP">结束剩余退仓</el-radio><el-radio v-if="!detail.child_returns.length&&!detail.continuation_state" v-hasPermi="['warehouse:purchaseReturn:continue']" label="CONTINUE">继续退剩余数量</el-radio></el-radio-group><p>保留已出库及已扣账结果，按原来源处理未出库数量。</p><p v-if="choice==='CONTINUE'">原占用释放成功后生成关联草稿，带入剩余商品、原成本与收货信息，须重新审核。</p><el-table :data="remainingRows" size="small"><el-table-column label="原SKU / 批次" min-width="250"><template slot-scope="{row}">{{row.sku_sn}}<div class="muted">{{row.batch_code}} · {{row.inventory_type==='ZP'?'正品':'次品'}}</div></template></el-table-column><el-table-column label="已扣账 / 未出库"><template slot-scope="{row}">{{row.posted_quantity}} / {{Number(row.quantity)-Number(row.accepted_quantity)}} {{row.stock_unit}}</template></el-table-column><el-table-column label="预计释放原占用"><template slot-scope="{row}">{{releasePreview(row)}}</template></el-table-column></el-table></template>
   <el-form label-position="top" size="small">
    <template v-if="kind==='FUNDS'"><el-form-item label="凭证类型"><el-radio-group v-model="fundKind"><el-radio label="REFUND">退款凭证</el-radio><el-radio label="CREDIT">抵扣凭证</el-radio></el-radio-group></el-form-item><el-form-item label="本次登记金额" required><el-input-number v-model="amount" :min="0.01" :max="Number(detail.funds_remaining)" :precision="2"/><span class="hint">当前剩余可登记 ¥{{money(detail.funds_remaining)}}</span></el-form-item></template>
    <p v-if="kind==='REVERSAL'&&original">冲销原凭证 #{{original.id}}，金额 ¥{{money(original.amount)}}。系统追加冲销记录，原记录保留。</p>
    <el-form-item v-if="kind==='SUPPLIER'" label="本次供应商结果"><el-radio-group v-model="decision"><el-radio label="ACCEPT">确认签收</el-radio><el-radio label="REFUSE">确认拒收</el-radio><el-radio label="SHORT">短收待核对</el-radio></el-radio-group></el-form-item>
    <el-table v-if="['SUPPLIER','RECLAIM'].includes(kind)" :data="rows" size="small">
     <el-table-column label="实际商品 / 批次 / 质量" min-width="270"><template slot-scope="{row}"><strong>{{row.goods_name}}</strong><div class="muted">{{row.sku_sn}} · {{row.batch_code}} · {{row.inventory_type==='ZP'?'正品':'次品'}}</div></template></el-table-column>
     <el-table-column label="实际退仓 / 已签收 / 已拒收" min-width="180"><template slot-scope="{row}">{{row.posted_quantity}} / {{row.supplier_received_quantity}} / {{row.supplier_refused_quantity}} {{row.stock_unit}}</template></el-table-column>
     <el-table-column :label="kind==='SUPPLIER'?'未确认数量':'尚可安排收回'" width="130"><template slot-scope="{row}">{{limit(row)}} {{row.stock_unit}}</template></el-table-column>
     <el-table-column label="本次数量" width="185"><template slot-scope="{row}"><el-input-number v-model="row.selected" :min="0" :max="limit(row)" :precision="0" size="small" :disabled="limit(row)===0"/></template></el-table-column>
    </el-table>
    <return-carrier-capture v-if="kind==='RECLAIM'" v-model="logistics" :purchase-id="detail.purchase_id" :active="visible"/>
    <el-form-item :label="['FUNDS','REVERSAL','SUPPLIER'].includes(kind)?'凭证及核对依据':'处理原因与协商依据'" required><el-input v-model.trim="reason" type="textarea" :maxlength="kind==='REMAINING'?200:1000" :rows="3" show-word-limit/></el-form-item>
   </el-form><el-alert v-if="error" :title="error" type="error" :closable="false"/>
  </template>
  <span slot="footer"><el-button :disabled="busy" @click="visible=false">返回</el-button><el-button type="primary" :loading="busy" @click="submit">{{buttonLabel}}</el-button></span>
 </el-dialog>
</template>
<script>
import ReturnCarrierCapture from './ReturnCarrierCapture'
import {returnAction} from '@/api/purchase/returns'
import PurchaseReturnCarrierSelect from './PurchaseReturnCarrierSelect'
const key=()=> 'PRF'+Date.now()+Math.random().toString(36).slice(2)
export default{
 components:{ReturnCarrierCapture,PurchaseReturnCarrierSelect},
 props:{detail:Object},data:()=>({visible:false,kind:'',choice:'STOP',decision:'ACCEPT',fundKind:'REFUND',amount:0,original:null,rows:[],logistics:{standard_id:'',carrier_unverified:false,raw_carrier_code:'',raw_carrier_name:'',waybill:''},reason:'',requestKey:'',version:0,busy:false,error:'',titles:{REMAINING:'处理剩余退仓数量',FUNDS:'登记供应商款项凭证',REVERSAL:'冲销原款项凭证',SUPPLIER:'登记供应商收货结果',RECLAIM:'创建拒收收回入库单'}}),
 computed:{remainingRows(){return this.rows.filter(l=>Number(l.quantity)>Number(l.accepted_quantity))},hint(){return ({REMAINING:'仓库未结束时先确认停止结果；取得最终出库凭证后按原来源释放。已出库部分保留。',FUNDS:'登记已核对的退款或抵扣凭证，不执行银行付款。累计金额受实际退仓净货值约束。',REVERSAL:'冲销用于更正已登记凭证，不执行资金划转；更正后可重新登记。',SUPPLIER:'按本次实际签收、拒收或短收凭证登记。此处不改变本仓库存；短收数量保留待核查。',RECLAIM:'仅安排已实际退仓且供应商确认拒收的商品。草稿须审核，仓库真实实收后才恢复库存。'})[this.kind]},buttonLabel(){return this.kind==='REMAINING'?(this.choice==='CONTINUE'?'结束原单并生成后续草稿':'确认结束剩余退仓'):this.kind==='RECLAIM'?'保存收回入库草稿':this.kind==='REVERSAL'?'确认追加冲销记录':'保存凭证与结果'}},
 methods:{can(action){const permissions=this.$store.getters.permissions||[];return permissions.includes('*:*:*')||permissions.includes('warehouse:purchaseReturn:'+action)},releasePreview(row){const stock=this.detail.stock&&this.detail.stock.lines&&this.detail.stock.lines.find(l=>Number(l.line_key)===Number(row.id));if(!stock)return this.detail.state==='CANCELED'?'原占用已释放':'待查询原库存余额';const remaining=Number(stock.quantity)-Number(stock.consumed_quantity)-Number(stock.released_quantity),raw=stock[row.inventory_type==='ZP'?'zp_available_number':'cp_available_number'],free=Number(raw);if(raw==null||!Number.isFinite(free))return remaining+' '+row.stock_unit+'；批次可用待确认';return remaining+' '+row.stock_unit+'；批次可用 '+free+' → '+(free+remaining)},money(v){return Number(v||0).toFixed(2)},open(kind,original){this.kind=kind;this.original=original||null;this.choice=this.detail.state==='CANCELED'||!this.can('cancel')?'CONTINUE':'STOP';this.decision='ACCEPT';this.fundKind='REFUND';this.reason='';this.logistics={standard_id:'',carrier_unverified:false,raw_carrier_code:'',raw_carrier_name:'',waybill:''};this.amount=Number(this.detail.funds_remaining)||0;this.rows=this.detail.lines.map(l=>({...l,selected:0}));this.version=this.detail.control_version;this.requestKey=key();this.error='';this.visible=true},limit(row){return Math.max(0,this.kind==='RECLAIM'?Number(row.supplier_refused_quantity)-Number(row.reclaim_claimed_quantity||0):Number(row.posted_quantity)-Number(row.supplier_received_quantity)-Number(row.supplier_refused_quantity))},async submit(){if(this.busy)return;if(!this.reason)return this.$message.warning('请填写处理依据');const body={request_key:this.requestKey,control_version:this.version};let action;
   if(this.kind==='REMAINING'){action=this.choice==='CONTINUE'?'continue':'cancel';body.reason=this.reason}
   else if(['FUNDS','REVERSAL'].includes(this.kind)){action='funds';Object.assign(body,{funds_state:this.kind==='REVERSAL'?'REVERSAL':this.fundKind,evidence:this.reason,amount:this.amount});if(this.original)body.original_id=this.original.id}
   else{const selected=this.rows.filter(l=>Number(l.selected)>0);if(!selected.length)return this.$message.warning('请填写至少一行本次数量');body.lines=selected.map(l=>({line_id:l.id,quantity:Number(l.selected)}));if(this.kind==='SUPPLIER'){action='supplier-receipt';Object.assign(body,{decision:this.decision,evidence:this.reason})}else{if(!this.logistics.waybill||(!this.logistics.carrier_unverified&&!this.logistics.standard_id)||(this.logistics.carrier_unverified&&!this.logistics.raw_carrier_code&&!this.logistics.raw_carrier_name))return this.$message.warning('请填写供应商实际退回快递及运单号');action='reclaims';Object.assign(body,this.logistics,{reason:this.reason})}}
   this.busy=true;this.error='';try{const r=await returnAction(this.detail.id,action,body);this.visible=false;this.$emit('changed',this.detail.id);if(this.kind==='RECLAIM')this.$emit('reclaim',r.data)}catch(e){this.error=e.message||'操作未完成，请刷新核对原单'}finally{this.busy=false}}
 }
}
</script>
<style scoped>.choices{display:flex;gap:22px;margin:22px 0}.muted,.hint{font-size:12px;color:#7a899d;line-height:1.8;overflow-wrap:anywhere}.hint{margin-left:12px}.el-form{margin-top:18px}.el-table{margin:20px 0}</style>
